#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
#
# Prod setup for Troop 813 HQ (issue #19): the steps only a human can do
# (ADR 0005), in the one order that works. Run from anywhere in the repo:
#
#   scripts/prod-setup-wizard.sh
#
# Saves BILLING_ACCOUNT_ID to the gitignored root .env so a re-run remembers it.
# Every stage is safe to repeat.

run_wizard() {

cd "$(git rev-parse --show-toplevel)"
PROJECT=troop-813
ORIGIN=https://troop-813-hq.web.app

# run_workflow FILE: start FILE on trunk and wait for it, offering a retry on failure.
run_workflow() {
  local file="$1" id
  while true; do
    say "Starting $file on trunk…"
    gh workflow run "$file" --ref trunk
    sleep 8
    id=$(gh run list --workflow "$file" --branch trunk --limit 1 --json databaseId -q '.[0].databaseId')
    if gh run watch "$id" --exit-status --interval 10; then
      printf '  %s✓ %s passed%s\n' "$GREEN" "$file" "$RESET"
      return 0
    fi
    warn "$file failed. Its failed steps:"
    gh run view "$id" --log-failed | tail -n 40 || true
    confirm "Run $file again (e.g. after a fix is pushed)?" || return 1
  done
}

TOTAL_STAGES=9

banner "Troop 813 HQ: prod setup"

# ─────────────────────────────────────────────────────────────────────────
stage "Check your tools"
say "You need gcloud logged in as a troop-813 owner, gh logged in to GitHub,"
say "and this repo's trunk (with issue #19's commit) pushed to GitHub."
gcloud auth list --filter=status:ACTIVE --format='value(account)' | sed 's/^/  gcloud account: /'
if gh auth status >/dev/null 2>&1; then say "gh: logged in"; else warn "gh is not logged in: run 'gh auth login' in another terminal"; fi
git fetch -q origin trunk || true
if ! git cat-file -e origin/trunk:terraform/bootstrap.sh 2>/dev/null; then
  warn "origin/trunk doesn't have terraform/bootstrap.sh yet. Merge #19 into trunk and push it first."
fi
if [[ "$(gh repo view markgoho/troop-813 --json visibility -q .visibility 2>/dev/null || true)" == "PRIVATE" ]]; then
  warn "The repo is PRIVATE: Actions minutes are capped (ADR 0005 assumes public)."
fi
note "Wrong gcloud account? Ctrl-C, run 'gcloud auth login', then re-run this wizard."
pause "All set? Press Enter."

# ─────────────────────────────────────────────────────────────────────────
stage "Billing account (dedicated, Paid) linked to troop-813"
say "ADR 0001: a billing account used only by troop-813, so free quotas aren't"
say "shared with other projects, upgraded to Paid now (not left on the trial)."
open_url "https://console.cloud.google.com/billing/create"
step "Create a billing account named 'Troop 813' (skip if you already made one)."
step "If its Overview page shows 'Activate' or 'Upgrade to a paid account', do it."
step "Copy its Billing account ID (Billing → Account management, like 0X0X0X-0X0X0X-0X0X0X)."
ask BILLING_ACCOUNT_ID "Paste the billing account ID:"
write_env BILLING_ACCOUNT_ID "$BILLING_ACCOUNT_ID"
current=$(gcloud billing projects describe "$PROJECT" --format='value(billingAccountName)' 2>/dev/null || true)
if [[ "$current" == "billingAccounts/$BILLING_ACCOUNT_ID" ]]; then
  say "troop-813 is already linked to it."
elif confirm "Link troop-813 to billing account $BILLING_ACCOUNT_ID now?"; then
  gcloud billing projects link "$PROJECT" --billing-account="$BILLING_ACCOUNT_ID"
else
  SKIPPED+=("link billing: gcloud billing projects link $PROJECT --billing-account=$BILLING_ACCOUNT_ID")
fi
pause

# ─────────────────────────────────────────────────────────────────────────
stage "\$1 budget alert"
say "An email when spend passes \$1. It only alerts; there's no kill switch (ADR 0001)."
open_url "https://console.cloud.google.com/billing/$BILLING_ACCOUNT_ID/budgets/create"
step "Name: troop-813. Projects: troop-813 only. Next."
step "Budget type: Specified amount. Target amount: 1 (USD). Next."
step "Thresholds: 50%, 90%, 100% of Actual. Keep 'Email alerts to billing admins and users'."
step "Finish."
pause "Budget saved? Press Enter."

# ─────────────────────────────────────────────────────────────────────────
stage "Bootstrap: state bucket, WIF, Terraform SA"
say "terraform/bootstrap.sh makes what CI needs before Terraform can run:"
note "gs://troop-813-tfstate (versioned), a WIF pool+provider trusting only trunk on"
note "markgoho/troop-813, and terraform@troop-813 (owner). Idempotent; never creates a project."
if confirm "Run terraform/bootstrap.sh against troop-813 now?"; then
  bash terraform/bootstrap.sh
else
  SKIPPED+=("bootstrap: bash terraform/bootstrap.sh")
fi
pause

# ─────────────────────────────────────────────────────────────────────────
stage "First Terraform apply (CI)"
say "Terraform runs only in CI (terraform.yml). This starts it on trunk and waits."
say "It enables APIs and creates Firestore, Artifact Registry, Cloud Run (placeholder"
say "image), the SAs, Identity Platform and the troop-813-hq Hosting site."
note "api.yml and web.yml probably failed on the push that brought #19: nothing existed"
note "yet. That's expected; stage 8 re-runs them."
if ! run_workflow terraform.yml; then
  SKIPPED+=("terraform.yml green (gh workflow run terraform.yml --ref trunk)")
  warn "Don't enable the Google provider until terraform.yml is green."
fi
pause

# ─────────────────────────────────────────────────────────────────────────
stage "Enable Google sign-in"
say "Done in the console so the OAuth client secret never reaches CI (ADR 0005)."
warn "If Authentication shows a 'Get started' button, STOP: Terraform hasn't applied yet."
open_url "https://console.firebase.google.com/project/$PROJECT/authentication/providers"
step "Sign-in method → Add new provider → Google."
step "Toggle Enable. Public-facing name: Troop 813 HQ. Support email: yours."
step "Save."
pause "Google shows as Enabled? Press Enter."

# ─────────────────────────────────────────────────────────────────────────
stage "Redirect URI for troop-813-hq.web.app"
say "Sign-in uses the app's own origin as authDomain (issue #14), so Google must"
say "accept $ORIGIN/__/auth/handler as a redirect."
open_url "https://console.cloud.google.com/apis/credentials?project=$PROJECT"
step "OAuth 2.0 Client IDs → 'Web client (auto created by Google Service)'."
step "Authorized JavaScript origins → Add URI: $ORIGIN"
step "Authorized redirect URIs → Add URI: $ORIGIN/__/auth/handler"
step "Save. (It can take a few minutes to apply.)"
pause "Saved? Press Enter."

# ─────────────────────────────────────────────────────────────────────────
stage "Deploy the API, then HQ"
say "api.yml first (builds the image, replaces the placeholder), then web.yml"
say "(HQ, rules, indexes; its smoke test calls /api/health through Hosting)."
if run_workflow api.yml; then
  run_workflow web.yml || SKIPPED+=("web.yml green (gh workflow run web.yml --ref trunk)")
else
  SKIPPED+=("api.yml green (gh workflow run api.yml --ref trunk), then web.yml")
fi
pause

# ─────────────────────────────────────────────────────────────────────────
stage "Verify prod"
if curl -fsS "$ORIGIN/" | grep -q manifest.webmanifest; then
  printf '  %s✓%s %s serves HQ\n' "$GREEN" "$RESET" "$ORIGIN"
else
  warn "$ORIGIN/ did not serve HQ"; SKIPPED+=("$ORIGIN serving HQ")
fi
health=$(curl -fsS "$ORIGIN/api/health" || true)
if [[ "$health" == *'"status":"ok"'* ]]; then
  printf '  %s✓%s /api/health: %s\n' "$GREEN" "$RESET" "$health"
else
  warn "/api/health answered: ${health:-nothing}"; SKIPPED+=("$ORIGIN/api/health returning ok")
fi
open_url "$ORIGIN"
step "On the Pixel Tablet / your phone in Chrome: menu → Install app (or Add to Home screen)."
step "The installed app is '813 HQ' and opens fullscreen."
pause "Done? Press Enter."

finish
}

run_wizard "$@"; exit
